__NUXT_JSONP__("/inclusion/noticias/unidas_alza_la_voz_problemas_a_los_que_las_mujeres_trabajadoras_de_plataformas_digitales_se_enfrentan", (function(a,b,c,d,e){return {data:[{post:{slug:"unidas_alza_la_voz_problemas_a_los_que_las_mujeres_trabajadoras_de_plataformas_digitales_se_enfrentan",title:"Unidas alza la voz: problemas a los que las mujeres trabajadoras de plataformas digitales se enfrentan",date:"2026-01-29T21:34:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F39618c53-e3c4-449e-bbb9-a79358a36b14\u002F-\u002Fpreview\u002F","img-alt":"UNIDAS",autor:"Fátima Chávez, La Crónica",link:"https:\u002F\u002Fwww.cronica.com.mx\u002Fnacional\u002F2026\u002F01\u002F29\u002Funidas-alza-la-voz-problemas-a-los-que-las-mujeres-trabajadoras-de-plataformas-digitales-se-enfrentan\u002F",category:"inclusion",extracto:"El actual programa de la reforma establece que para acceder a estos servicios la cuenta del conductor debe tener un ingreso cercano a los 19 mil pesos mensuales y en caso de no alcanzarla no podrá tener derecho a recibir un seguro médico.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Como parte de las iniciativas que aporten a la implementación de una Reforma en Materia de Trabajo en Plataformas digitales, que actualmente se encuentra en un programa piloto, se llevó a cabo un evento organizado por la fundación Unidas, una red de mujeres que colaboran por el trabajo justo y que buscan promover la agenda del trabajo en México. Durante el evento se abordaron las distintas problemáticas a las que la mujeres trabajadoras de estas plataformas se enfrentan día con día y las opciones que sugieren deberían ser tratadas para mejorar el lanzamiento oficial de la reforma"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El Coordinador Inclusión y Desarrollo Sostenible del think thank Ethos Innovación en Políticas Públicas, Néstor Genis, compartió algunas de las problemáticas que las trabajadoras han reportado acerca de su labor así como de la relación con la empresa y la reforma, con la intención de acortar o cerrar la brecha laboral por cuestiones de género que existe actualmente ."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La primera es la persistencia de violencia y acoso por parte de los clientes que solicitan el servicio, la cual no es atendida ni sancionada de manera adecuada y que de hecho se señala que muchas veces la aplicación sanciona a la conductora por cancelar un servicio ya que el algoritmo de la plataforma no da un seguimiento adecuado a la situación de violencia y en la mayoría de los casos son bots los que atienden la queja."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El segundo, la exclusión que les dificulta a las trabajadoras obtener su derecho a un servicio médico social digno, esto debido a que actualmente existen requisitos y cuotas mínimas para permitir el acceso a este servicio. El actual programa de la reforma establece que para acceder a estos servicios la cuenta del conductor debe tener un ingreso cercano a los 19 mil pesos mensuales y en caso de no alcanzarla no podrá tener derecho a recibir un seguro médico."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Al respecto, Veronica Alvarez, conductora y representante de la colectiva lady drivers declaró que dentro de su colectiva integrada por al menos 30 mujeres, solo 10 de ellas alcanzan a cubrir de manera periódica estas cuotas, debido a que muchas de las mujeres que trabajan en este sector lo hacen precisamente por que pueden laborar de acuerdo a horarios que les permitan no descuidar a sus familias."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Precisamente otra de las problemáticas son las jornadas a las que muchas veces las trabajadoras se ven sujetas para lograr generar más ingresos o llegar a la meta que les permita los beneficios de un seguro médico."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Las integrantes de las colectivas que representan a las trabajadoras denuncian estas problemáticas con la intención de que se realicen los ajustes pertinentes a la reforma para que puedan trabajar de una manera más segura y digna sin que la violencia de género invada sus labores o la falta de atención médica les cause inseguridad al conducir hacia sus destinos de servicio."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El Director General de Previsión Social Omar Estefan acudió como invitado al evento y declaró al respecto que aunque la reforma actualmente se encuentra en un periodo de prueba se está trabajando para que se consideren todas las opiniones y las medidas pertinentes para que estos problemas sean atendidos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Declaró que ya se ha comenzado la inspección a los problemas que se han observado no solo de parte de las cuentas de trabajadores sino de las empresas dueñas de las plataformas y que ahora el objetivo es crear un sistema en el que para que ambos sectores puedan obtener beneficios, así como dar un enfoque dirigido a las solicitudes de las mujeres trabajadoras de plataformas digitales."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Funidas_alza_la_voz_problemas_a_los_que_las_mujeres_trabajadoras_de_plataformas_digitales_se_enfrentan",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2026-07-19T00:56:17.264Z")));